function Eyebrow({children}:any){return <div className="eyebrow">{children}</div>}function Label({children}:any){return <label className="label">{children}</label>}function Field({label,value,set,type='text',children}:any){return <label className="field"><span>{label}</span>{children||<input type={type} value={value??''} onChange={e=>set(type==='number'?Number(e.target.value):e.target.value)}/>}</label>}function Options({values,selected,set,labels}:any){return <div className="options">{values.map((v:string,i:number)=><button type="button" key={v} className={selected===v?'option active':'option'} onClick={()=>set(v)}>{labels[i]}</button>)}</div>}function K({label,value}:any){return <div className="k"><small>{label}</small><b>{value}</b></div>}
